target.css:
:root {
  --ink: #14213d;
  --navy: #17365d;
  --ice: #eef8fb;
  --white: #ffffff;
  --line: #b8d0dc;
  --coral: #f07167;
  --gold: #f6bd60;
  --mint: #6bc7b0;
  --slate: #60758a;
}

.curling-board,
.curling-board * {
  box-sizing: border-box;
}

.curling-board {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--white);
  color: var(--ink);
}

.board-head {
  min-height: 66px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: var(--navy);
  color: var(--white);
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 5px 7px;
  border-radius: 6px;
  background: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.live-pill i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--white);
}

.draw-title {
  flex: 1;
}

.draw-title h1,
.draw-title p,
.team-panel h2,
.hammer-note,
.board-footer p {
  margin: 0;
}

.draw-title h1 {
  font-size: 18px;
  line-height: 1.1;
  letter-spacing: -.02em;
}

.draw-title p {
  margin-top: 3px;
  color: var(--line);
  font-size: 11px;
}

.board-head time {
  color: var(--gold);
  font-size: 15px;
  font-weight: 800;
}

.board-content {
  display: grid;
  grid-template-columns: 176px 1fr;
  min-height: 153px;
}

.team-panel {
  padding: 13px 14px;
  border-right: 1px solid var(--line);
  background: var(--ice);
}

.team-panel h2 {
  color: var(--slate);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .1em;
}

.teams,
.legend,
.end-numbers {
  padding: 0;
  margin: 0;
  list-style: none;
}

.teams {
  display: grid;
  gap: 10px;
  margin-top: 10px;
}

.team {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stone {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 50%;
  color: var(--white);
  font-size: 13px;
  line-height: 1;
}

.coral-team .stone { background: var(--coral); }
.mint-team .stone { background: var(--mint); }

.team-copy {
  display: grid;
  gap: 2px;
}

.team-copy strong {
  font-size: 11px;
  line-height: 1.1;
}

.team-copy small {
  color: var(--slate);
  font-size: 10px;
}

.hammer-note {
  margin-top: 11px;
  color: var(--slate);
  font-size: 10px;
  font-weight: 700;
}

.hammer-note::first-letter {
  color: var(--gold);
}

.score-panel {
  display: grid;
  grid-template-rows: 38px 37px 37px 41px;
}

.ends-head,
.score-row {
  display: grid;
  grid-template-columns: 35px 1fr;
  align-items: center;
  padding: 0 13px;
}

.ends-head {
  border-bottom: 1px solid var(--line);
  color: var(--slate);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .08em;
}

.end-numbers {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  text-align: center;
}

.score-row {
  border-bottom: 1px solid var(--line);
}

.score-row b {
  display: grid;
  height: 22px;
  place-items: center;
  border-left: 1px solid var(--line);
  font-size: 13px;
}

.row-mark {
  font-size: 12px;
  font-weight: 900;
}

.coral-score .row-mark { color: var(--coral); }
.mint-score .row-mark { color: var(--mint); }

.score-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 14px;
  background: var(--ice);
  color: var(--slate);
  font-size: 11px;
}

.score-footer strong {
  color: var(--navy);
  font-size: 17px;
  letter-spacing: .08em;
}

.board-footer {
  display: flex;
  align-items: center;
  gap: 13px;
  min-height: 45px;
  padding: 8px 14px;
  border-top: 1px solid var(--line);
  background: var(--white);
}

.board-footer p {
  color: var(--slate);
  font-size: 10px;
}

.legend {
  display: flex;
  gap: 8px;
  margin-left: auto;
}

.legend li {
  display: flex;
  align-items: center;
  gap: 4px;
  color: var(--slate);
  font-size: 10px;
}

.legend i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
}

.coral-key { background: var(--coral); }
.mint-key { background: var(--mint); }

.board-footer button {
  border: 1px solid var(--navy);
  border-radius: 6px;
  padding: 6px 8px;
  background: var(--white);
  color: var(--navy);
  font-size: 10px;
  font-weight: 800;
}

